using NUnit.Framework;

[TestFixture]
public class FindLongestWordTests
{
    [Test]
    public void Returns_Longest_Word()
    {
        var result = FindLongestWord("I love automation testing");
        Assert.That(result, Is.EqualTo("automation"));
    }

    private string FindLongestWord(string sentence)
    {
        var words = sentence.Split(' ', StringSplitOptions.RemoveEmptyEntries);
        if (words.Length == 0)
            return string.Empty;

        string longest = words[0];

        foreach (var word in words)
        {
            if (word.Length > longest.Length)
                longest = word;
        }

        return longest;
    }
}
